// Find the rows you have said yes to.
//
// Deliberately generous about what counts as yes -- you are typing this on a
// phone, and "Yes ", "y", "YES", "approve" should all work. Deliberately
// strict about everything else: anything that is not clearly a yes is left
// alone, because the failure mode here is applying to a job you did not
// choose.

const YES = /^\s*(y|yes|ok|okay|approve|approved|go)\s*$/i;

const rows = [];
for (const { json: r } of $input.all()) {
  // The column may be titled a few ways depending on how you added it.
  const mark = String(
    r['Approve?'] ?? r['Approve'] ?? r['approve'] ?? r['APPROVE'] ?? ''
  );
  if (!YES.test(mark)) continue;

  const id = String(r['ID'] ?? '').trim();
  if (!/^\d+$/.test(id)) continue;

  // Only act on rows still waiting. Without this, a yes left in the sheet
  // would be re-sent on every sweep for as long as it sat there.
  const status = String(r['Status'] ?? '').toUpperCase();
  if (!status.includes('WAITING')) continue;

  rows.push({
    id,
    title: String(r['Job Title'] ?? ''),
    company: String(r['Company'] ?? ''),
    score: r['Score'] ?? '',
    honesty: String(r['Honesty Flag'] ?? ''),
  });
}

return rows.map((json) => ({ json }));

// One message per sweep, not one per job.
const approved = $('Find your approvals').all().map((i) => i.json);
if (!approved.length) return [];

const lines = [
  `${approved.length} application${approved.length === 1 ? '' : 's'} approved from the sheet.`,
  '',
];
for (const a of approved) {
  lines.push(`  ${a.score}  ${a.title} - ${a.company}`);
  if (a.honesty) lines.push(`       ${a.honesty}`);
}
lines.push(
  '',
  'Nothing has been sent. These are on your shortlist: open each posting,',
  'read the letter, and apply yourself.'
);

return [{ json: { title: 'Shortlisted', body: lines.join(String.fromCharCode(10)) } }];
